{
  "name": "二维数据视图组件",
  "name_en": "2D Data Viewer",
  "manufacturer": "",
  "description": "一个用于实验软件中的非物理二维数据显示组件，用于绘制和操作图像数据。它支持图像显示、ROI 区域、十字光标、线剖面、直方图、图例、坐标轴标签与缩放，常用于相机图像或扫描成像结果的实时可视化与分析。",
  "description_en": "A non-physical 2D data visualization component used in laboratory software to plot and manipulate image data. It supports image display, ROIs, crosshair, lineouts, histogram, legend, axis labels, and axis scaling, and is commonly used for real-time visualization and analysis of camera images or scanned imaging data.",
  "tag_hints": [
    "2D image visualization",
    "ROI display",
    "crosshair lineouts",
    "histogram display",
    "axis scaling",
    "scientific plotting",
    "scan image viewer"
  ],
  "actions": [
    {
      "action_name": "auto-clear_plot_item",
      "description": "清除绘图项中的显示内容。",
      "description_en": "Clear the displayed content from the plot item."
    },
    {
      "action_name": "auto-set_image_displayer",
      "description": "设置二维图像数据的显示方式。",
      "description_en": "Set the display mode for 2D image data."
    },
    {
      "action_name": "auto-show_roi_target",
      "description": "显示或隐藏 ROI 目标区域标记。",
      "description_en": "Show or hide the ROI target marker."
    },
    {
      "action_name": "auto-move_scale_roi_target",
      "description": "移动并缩放 ROI 目标区域。",
      "description_en": "Move and resize the ROI target area."
    },
    {
      "action_name": "auto-setup_widgets",
      "description": "初始化界面控件。",
      "description_en": "Set up the interface widgets."
    },
    {
      "action_name": "auto-setup_graphs",
      "description": "初始化图形显示区域布局。",
      "description_en": "Set up the graph display layout."
    },
    {
      "action_name": "auto-setup_actions",
      "description": "初始化界面操作项。",
      "description_en": "Set up the interface actions."
    },
    {
      "action_name": "auto-update_colors",
      "description": "更新图像或通道的显示颜色。",
      "description_en": "Update the display colors of images or channels."
    },
    {
      "action_name": "auto-connect_things",
      "description": "连接界面内部的信号与槽。",
      "description_en": "Connect internal interface signals and slots."
    },
    {
      "action_name": "auto-show_legend",
      "description": "显示或隐藏图例。",
      "description_en": "Show or hide the legend."
    },
    {
      "action_name": "auto-add_roi_displayer",
      "description": "添加一个 ROI 显示项。",
      "description_en": "Add an ROI displayer."
    },
    {
      "action_name": "auto-remove_roi_displayer",
      "description": "移除一个 ROI 显示项。",
      "description_en": "Remove an ROI displayer."
    },
    {
      "action_name": "auto-update_roi_channels",
      "description": "更新 ROI 使用的通道设置。",
      "description_en": "Update the channel selection used by an ROI."
    },
    {
      "action_name": "auto-prepare_ui",
      "description": "准备并配置用户界面。",
      "description_en": "Prepare and configure the user interface."
    },
    {
      "action_name": "auto-display_images",
      "description": "显示二维图像数据。",
      "description_en": "Display 2D image data."
    },
    {
      "action_name": "auto-display_roi_lineouts",
      "description": "显示 ROI 的线剖面数据。",
      "description_en": "Display ROI lineout data."
    },
    {
      "action_name": "auto-display_crosshair_lineouts",
      "description": "显示十字光标位置的线剖面数据。",
      "description_en": "Display lineout data at the crosshair position."
    },
    {
      "action_name": "auto-show_lineout_widgets",
      "description": "显示线剖面相关控件。",
      "description_en": "Show the lineout-related widgets."
    },
    {
      "action_name": "auto-roi_clicked",
      "description": "响应 ROI 选择或点击状态变化。",
      "description_en": "Handle ROI selection or click state changes."
    },
    {
      "action_name": "auto-notify_visibility_data_displayer",
      "description": "通知数据显示器可见性状态已变化。",
      "description_en": "Notify that the data displayer visibility has changed."
    },
    {
      "action_name": "auto-show_hide_histogram",
      "description": "显示或隐藏直方图。",
      "description_en": "Show or hide the histogram."
    },
    {
      "action_name": "auto-prepare_image_widget_for_lineouts",
      "description": "为线剖面显示调整图像控件布局。",
      "description_en": "Prepare the image widget layout for lineout display."
    },
    {
      "action_name": "auto-collapse_lineout_widgets",
      "description": "折叠线剖面控件区域。",
      "description_en": "Collapse the lineout widget area."
    },
    {
      "action_name": "auto-lock_aspect_ratio",
      "description": "锁定图像显示的纵横比。",
      "description_en": "Lock the image display aspect ratio."
    },
    {
      "action_name": "auto-move_left_splitter",
      "description": "移动左侧分割条位置。",
      "description_en": "Move the left splitter position."
    },
    {
      "action_name": "auto-move_right_splitter",
      "description": "移动右侧分割条位置。",
      "description_en": "Move the right splitter position."
    },
    {
      "action_name": "auto-set_crosshair_position",
      "description": "设置十字光标位置。",
      "description_en": "Set crosshair position."
    },
    {
      "action_name": "auto-show_hide_crosshair",
      "description": "显示或隐藏十字光标。",
      "description_en": "Show or hide the crosshair."
    },
    {
      "action_name": "auto-show_ROI_select",
      "description": "显示 ROI 选择界面。",
      "description_en": "Show the ROI selection interface."
    },
    {
      "action_name": "auto-set_image_labels",
      "description": "设置图像或通道标签。",
      "description_en": "Set image or channel labels."
    },
    {
      "action_name": "auto-set_axis_label",
      "description": "设置坐标轴标签与单位。",
      "description_en": "Set axis label and units."
    },
    {
      "action_name": "auto-set_axis_scaling",
      "description": "设置坐标轴缩放、偏移及标注。",
      "description_en": "Set axis scaling, offset, and labeling."
    },
    {
      "action_name": "auto-scale_axis",
      "description": "将坐标从原始轴转换到缩放后的轴。",
      "description_en": "Convert coordinates from the regular axes to the scaled axes."
    },
    {
      "action_name": "auto-unscale_axis",
      "description": "将坐标从缩放后的轴还原到原始轴。",
      "description_en": "Convert coordinates from the scaled axes back to the regular axes."
    }
  ]
}

